import React from 'react';
import {AbsoluteFill, Easing} from 'remotion';
import {interpolate, clamp, DUR, en, useS} from './kit';

const W = 1080;
const H = 1920;

const SALMO = en('Salmo');
const DIOS = en('Dios');
const AMPARO = en('amparo');
const FORTALEZA = en('fortaleza');
const PRONTO = en('pronto');
const AUXILIO = en('auxilio');
const TRIBULACIONES = en('tribulaciones');
const TEMEREMOS = en('temeremos');
const TIERRA = en('tierra');
const REMOVIDA = en('removida');
const MONTES = en('montes');
const CORAZON = en('corazón');
const MAR = en('mar');
const MORALEJA = en('Moraleja');
const PROFUNDA = en('profunda');
const PROMEE = en('promete');
const TORMENTA = en('tormenta');
const DETENGA = en('detenga');
const ASEGURA = en('asegura');
const REFUGIO = en('refugio');
const FIRME = en('firme');
const CAOS = en('caos');
const CONFIA = en('Confía');
const PRESENCIA = en('presencia');
const SOSTIENE = en('sostiene');
const PAZ = en('paz');
const RENACE = en('renace');
const TIEMBLA = en('tiembla');

const mezcla = (a: number[], b: number[], k: number) => `rgb(${a.map((x, i) => Math.round(x + (b[i] - x) * k)).join(',')})`;

const Cielo: React.FC<{k: number}> = ({k}) => {
  const arriba = mezcla([15, 10, 35], [20, 50, 90], k);
  const medio = mezcla([30, 20, 55], [60, 100, 160], k);
  const abajo = mezcla([45, 30, 65], [120, 160, 200], k);
  return <AbsoluteFill style={{background: `linear-gradient(180deg, ${arriba} 0%, ${medio} 55%, ${abajo} 100%)`}} />;
};

const NubesTormenta: React.FC<{s: number; k: number}> = ({s, k}) => (
  <AbsoluteFill style={{opacity: 1 - k}}>
    {Array.from({length: 6}).map((_, i) => {
      const x = -150 + i * 280 + Math.sin(s * 0.15 + i) * 60;
      const y = 180 + (i % 2) * 140 + Math.cos(s * 0.1 + i) * 30;
      return (
        <div key={i} style={{position: 'absolute', left: x, top: y, width: 420, height: 180, borderRadius: 120, background: 'radial-gradient(ellipse at 50% 40%, #3a3548, #1a1828 70%)', filter: 'blur(18px)', transform: `translateX(${Math.sin(s * 0.08 + i) * 40}px)`}} />
      );
    })}
  </AbsoluteFill>
);

const RayosLuz: React.FC<{s: number; k: number}> = ({s, k}) => (
  <AbsoluteFill style={{opacity: k * 0.7, mixBlendMode: 'screen'}}>
    {Array.from({length: 12}).map((_, i) => {
      const ang = -50 + i * 8.5 + Math.sin(s * 0.25 + i) * 1.5;
      return (
        <div key={i} style={{position: 'absolute', left: W / 2 - 30, top: 600, width: 60, height: 1600, transformOrigin: '50% 0%', transform: `rotate(${ang + 180}deg)`, background: 'linear-gradient(180deg, rgba(255,240,200,0.6), transparent 85%)', filter: 'blur(16px)'}} />
      );
    })}
  </AbsoluteFill>
);

const Montañas: React.FC<{s: number; k: number}> = ({s, k}) => {
  const temblor = Math.sin(s * 12) * 8 * (1 - k) * interpolate(s, [TIERRA, REMOVIDA + 1], [1, 0], clamp);
  const desplazamiento = interpolate(s, [MONTES, CORAZON + 0.5], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  return (
    <svg width={W + 200} height={700} style={{position: 'absolute', left: -100 + temblor, top: 800 + desplazamiento * 200}} viewBox={`0 0 ${W + 200} 700`}>
      <defs>
        <linearGradient id="mont1" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={mezcla([40, 35, 55], [80, 110, 150], k)} />
          <stop offset="100%" stopColor={mezcla([25, 22, 38], [45, 70, 100], k)} />
        </linearGradient>
        <linearGradient id="mont2" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={mezcla([50, 45, 65], [100, 130, 170], k)} />
          <stop offset="100%" stopColor={mezcla([30, 28, 45], [60, 90, 120], k)} />
        </linearGradient>
      </defs>
      <path d="M0 700 C 180 400, 350 500, 500 350 S 800 200, 950 300 L 1280 700 Z" fill="url(#mont1)" opacity={0.9} />
      <path d="M0 700 C 220 450, 400 550, 580 400 S 900 250, 1100 380 L 1280 700 Z" fill="url(#mont2)" opacity={0.7} />
    </svg>
  );
};

const Mar: React.FC<{s: number; k: number}> = ({s, k}) => {
  const ola = Math.sin(s * 1.8) * 12;
  const colorAgua = mezcla([10, 20, 45], [30, 80, 140], k);
  return (
    <svg width={W} height={500} style={{position: 'absolute', left: 0, top: 1420 + ola}} viewBox={`0 0 ${W} 500`}>
      <defs>
        <linearGradient id="mar" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={colorAgua} />
          <stop offset="100%" stopColor={mezcla([8, 15, 35], [20, 60, 110], k)} />
        </linearGradient>
      </defs>
      <path d={`M0 500 C 150 ${350 + ola * 2}, 300 ${400 - ola}, 540 ${370 + ola} S 900 ${320 - ola}, 1080 ${360 + ola} L 1080 500 L 0 500 Z`} fill="url(#mar)" />
      {[0, 1, 2].map((i) => (
        <path key={i} d={`M${100 + i * 300} ${380 + ola} Q ${250 + i * 300} ${340 + ola} ${400 + i * 300} ${380 + ola} Q ${550 + i * 300} ${420 + ola} ${700 + i * 300} ${380 + ola}`} fill="none" stroke="rgba(255,255,255,0.15)" strokeWidth={2} opacity={0.6} />
      ))}
    </svg>
  );
};

const Refugio: React.FC<{s: number; k: number}> = ({s, k}) => {
  const respira = Math.sin(s * 1.1) * 3;
  const aparece = interpolate(s, [AMPARO, FORTALEZA + 1], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
  const brillo = 0.3 + 0.7 * k + Math.sin(s * 2) * 0.1;
  return (
    <div style={{position: 'absolute', left: W / 2 - 120, top: 950 + respira, opacity: aparece, transform: `scale(${0.8 + 0.2 * k})`}}>
      <div style={{position: 'absolute', left: -200, top: -100, width: 640, height: 640, borderRadius: '50%', background: `radial-gradient(circle, rgba(255,230,180,${brillo * 0.4}), transparent 70%)`}} />
      <svg width={240} height={320} viewBox="0 0 240 320">
        <defs>
          <linearGradient id="roc" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={mezcla([80, 70, 60], [140, 130, 110], k)} />
            <stop offset="100%" stopColor={mezcla([50, 45, 40], [90, 85, 75], k)} />
          </linearGradient>
        </defs>
        <path d="M120 20 L 20 280 L 220 280 Z" fill="url(#roc)" stroke="rgba(255,220,160,0.5)" strokeWidth={2} />
        <rect x={85} y={180} width={70} height={100} rx={5} fill="#1a1510" />
        <rect x={100} y={195} width={40} height={70} rx={3} fill={`rgba(255,210,140,${0.6 + 0.4 * k})`} />
        <circle cx={108} cy={230} r={4} fill="rgba(255,180,80,0.8)" />
      </svg>
    </div>
  );
};

const ParticulasPaz: React.FC<{s: number; k: number}> = ({s, k}) => (
  <AbsoluteFill style={{opacity: k}}>
    {Array.from({length: 50}).map((_, i) => {
      const x = (i * 97) % W + Math.sin(s * 0.4 + i) * 50;
      const y = H - ((i * 173 + s * (12 + (i % 6) * 8)) % (H + 200));
      const r = 2 + (i % 3);
      return <div key={i} style={{position: 'absolute', left: x, top: y, width: r, height: r, borderRadius: r, background: '#fff8e0', opacity: 0.25 + 0.35 * Math.sin(s + i), filter: 'blur(0.5px)'}} />;
    })}
  </AbsoluteFill>
);

const Paloma: React.FC<{s: number; k: number}> = ({s, k}) => {
  const vuela = interpolate(s, [PAZ, RENACE + 1], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const x = 300 + vuela * 480 + Math.sin(s * 1.5) * 30;
  const y = 600 - vuela * 200 + Math.cos(s * 1.2) * 20;
  const ala = Math.sin(s * 8) * 25;
  return (
    <div style={{position: 'absolute', left: x, top: y, opacity: k * vuela, transform: `rotate(${-10 + vuela * 20}deg)`}}>
      <svg width={120} height={60} viewBox="0 0 120 60">
        <path d={`M60 30 Q ${40 - ala} ${10 - ala / 2} ${20 - ala} 30 Q ${40 - ala / 2} ${30 + ala / 3} 60 30 Q ${80 + ala / 2} ${30 + ala / 3} ${100 + ala} 30 Q ${80 + ala} ${10 - ala / 2} 60 30`} fill="none" stroke="#fff8e0" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" opacity={0.9} />
      </svg>
    </div>
  );
};

const Vigneta: React.FC = () => (
  <AbsoluteFill style={{background: 'radial-gradient(ellipse at 50% 45%, transparent 40%, rgba(5,5,20,0.65) 100%)'}} />
);

export const Escena: React.FC = () => {
  const {s} = useS();

  const kCaos = interpolate(s, [SALMO, TRIBULACIONES + 0.5], [1, 0], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const kPaz = interpolate(s, [AMPARO, PAZ + 2], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const kFinal = interpolate(s, [CONFIA, TIEMBLA + 1], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const kGlobal = Math.max(kPaz, kFinal);

  const zoom = 1.06 - 0.04 * (s / Math.max(DUR, 1)) + 0.02 * kFinal;
  const deriva = Math.sin(s * 0.12) * 15 * (1 - kGlobal);

  return (
    <AbsoluteFill style={{overflow: 'hidden', backgroundColor: '#0a0818'}}>
      <AbsoluteFill style={{transform: `scale(${zoom}) translateX(${deriva}px)`, transformOrigin: '50% 55%'}}>
        <Cielo k={kGlobal} />
        <NubesTormenta s={s} k={kCaos} />
        <RayosLuz s={s} k={kGlobal} />
        <Montañas s={s} k={kGlobal} />
        <Mar s={s} k={kGlobal} />
        <Refugio s={s} k={kGlobal} />
        <ParticulasPaz s={s} k={kGlobal} />
        <Paloma s={s} k={kGlobal} />
      </AbsoluteFill>
      <Vigneta />
    </AbsoluteFill>
  );
};
